149	fn run_search(args: &SearchArgs) -> Result<String, String> {
150	    let request = SearchRequest {
151	        root: &args.path,
152	        query: &args.query,
153	        exact: args.exact,
154	        allow_tests: args.tests,
155	        respect_ignore_files: !args.no_ignore,
156	        language: args.language,
157	    };
158	    let result = search_with_timeout(&registry(), &request, timeout(args)).map_err(|e| error_text(&e))?;
159	
160	    let mut ranked = result.ranked;
161	    let mut diagnostics = result.diagnostics;
162	    // Paths print relative to the working directory when they are under it, so every row spends fewer tokens.
163	    if let Some(cwd) = std::env::current_dir().ok().and_then(|dir| Utf8PathBuf::from_path_buf(dir).ok()) {
164	        for block in &mut ranked {
165	            relativize(&mut block.block.file, &cwd);
166	        }
167	        for diagnostic in &mut diagnostics {
168	            if let Some(path) = &mut diagnostic.path {
169	                relativize(path, &cwd);
170	            }
171	        }
172	    }
173	    if result.ceiling_hit {
174	        diagnostics.push(Diagnostic {
175	            kind: DiagnosticKind::Warning,
176	            path: None,
177	            message: format!(
178	                "{} files matched but hits were kept for only the first {DEFAULT_MAX_FILES}; narrow the query or path",
179	                result.files_total
180	            ),
181	        });
182	    }
183	    let budget = Budget { max_results: args.max_results, max_tokens: args.max_tokens };
184	    let total_before = ranked.len();
185	    let row_texts = search_row_texts(&ranked);
186	    let response = apply_budget(ranked, total_before, &budget, &row_texts, diagnostics);
187	    Ok(render_search(&response))
